const errors=[],report={};
const quantile=(a,q)=>[...a].sort((a,b)=>a-b)[Math.min(a.length-1,Math.floor(a.length*q))]||0;
async function ready(page){page.on('pageerror',e=>errors.push(e.message));await page.goto(origin);await page.waitForFunction(()=>window.__compiledAtlas?.ready&&__compiledAtlas.data.frame,{timeout:45000});}
async function nextFrame(page,fn,arg){const n=await page.evaluate(()=>__compiledAtlas.metrics.frames);if(fn)await page.evaluate(fn,arg);await page.waitForFunction(n=>__compiledAtlas.metrics.frames>n,n);}
try{
 const page=await browser.newPage({viewport:{width:1440,height:900}});let serverFrames=0;
 page.on('request',r=>{if(r.url().includes('/api/frame'))serverFrames++;});
 await ready(page);await page.waitForTimeout(700);
 assert.equal(await page.locator('#object-title').textContent(),'Earth');
 assert.equal(await page.evaluate(()=>__compiledAtlas.data.stats.catalog_stars),109401);
 const baseline=await page.evaluate(()=>({at:performance.now(),frames:__compiledAtlas.metrics.frames}));
 await page.waitForTimeout(2000);
