 for(const [key,min,max]of[['fps',1,120],['cols',60,320],['rows',20,160],['frames',1,1000000]])if(o[key]!==undefined){o[key]=Number(o[key]);if(!Number.isInteger(o[key])||o[key]<min||o[key]>max)throw Error(`--${key} must be ${min}..${max}`);}
